# Direct extraction by position
def extract_grid_at_marker(marker_pattern):
    idx = full_text.find(marker_pattern)
    if idx == -1:
        return None

    start = idx + len(marker_pattern)
    # Read until next major marker or end of relevant section
    section_end = full_text.find('\n\n', start)
    if section_end == -1:
        section = full_text[start:start+200]  # Rough limit
    else:
        section = full_text[start:section_end]

    # Parse rows
    grid = []
    current_row = []
    for char in section:
        if char.isdigit():
            current_row.append(char)
        elif char == ' ':
            if current_row:
                grid.append(int(''.join(current_row)))
                current_row = []
        else:
            if current_row:
                grid.append(int(''.join(current_row)))
                current_row = []

    # Group into rows (assume we know how many integers per row)
    n_cols = 27 if 'Test' in marker_pattern else 16
    rows = [grid[i*n_cols:(i+1)*n_cols] for i in range(len(grid)//n_cols)]

    return rows

